#!/usr/bin/env bash
# "make clean": removes build intermediates. --dist also removes the products in dist/.
set -Eeuo pipefail

root_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
case "${1:-}" in
    "") targets=() ;;
    --dist) targets=(dist) ;;
    *) echo "Usage: $0 [--dist]" >&2; exit 2 ;;
esac
# build/appicon.png, build/windows/icon.ico and build/windows/installer/project.nsi stay (versioned); the rest of build/ is generated by wails build
targets+=(build/bin build/windows/installer/tmp build/windows/installer/wails_tools.nsh build/windows/info.json build/windows/wails.exe.manifest frontend/dist dist/.stage)
# pnpm workspace node_modules (repo root and frontend): linked to another store, pnpm install refuses; rebuilt from .tools
targets+=(../node_modules frontend/node_modules)

for target in "${targets[@]}"; do
    if [[ -e "$root_dir/$target" ]]; then
        rm -rf -- "${root_dir:?}/$target"
        echo "removed $root_dir/$target"
    fi
done
# copies of .tools embedded in the exe (.gitkeep stays: go:embed needs the folder)
find "${root_dir:?}/backend/embedded" -maxdepth 1 -type f ! -name .gitkeep -print -delete
